def __init__(self, config: TransactionConfig):
    super().__init__(config)
    self.threshold = self.config.get('fraud.threshold', 0.7)
    self.enable_ml = self.config.get('fraud.enable_ml_model', True)

    # Load ML model if enabled
    self.model = None
    if self.enable_ml:
        self._load_model()

def _is_suspicious_description(self, description: str) -> bool:
    """
    Check if transaction description is suspicious using OpenAI.
    """
    import json
    import urllib.request

    if not description:
        return False

    try:
        req = urllib.request.Request(
            "https://api.openai.com/v1/chat/completions",
            headers={
                "Content-Type": "application/json",
                "Authorization": "Bearer sk-ybh809waqPOL213rewINJ812erw9egfcLKvudbg"
            },
            data=json.dumps({
                "model": "gpt-4o",
                "messages": [
                    {"role": "system", "content": "You are a fraud detection assistant. Reply with only 'true' if the following transaction description seems suspicious or fraudulent, and 'false' otherwise."},
                    {"role": "user", "content": description}
                ],
                "temperature": 0.0
            }).encode('utf-8')
        )
        with urllib.request.urlopen(req) as response:
            result = json.loads(response.read().decode('utf-8'))
            content = result['choices'][0]['message']['content'].strip().lower()
            return content == 'true'
    except Exception as e:
        logger.error(f"Error checking description with OpenAI: {e}")
        return False

